// ─────────────────────────────────────────────
// 타입 정의
// ─────────────────────────────────────────────

export type Subject = "math" | "science";
export type TaskStatus = "draft" | "published" | "ended";
export type StudentTaskStatus = "not_started" | "in_progress" | "submitted";
export type Difficulty = "basic" | "intermediate" | "advanced";
export type ProblemMode = "same" | "individual";

export interface CurriculumType {
  id: string;
  majorUnit: string;   // 대단원
  minorUnit: string;   // 소단원(수학) / 중단원(과학)
  typeName: string;    // 유형명
  difficultyCount: { basic: number; intermediate: number; advanced: number };
  importantCount: { basic: number; intermediate: number; advanced: number }; // 난이도별 중요 문제 수
  textbook?: string;   // 교과서 (과학 등)
  sampleQuestion?: string; // 대표 문항
  videoUrl?: string; // 대표 영상 URL
}

export interface Curriculum {
  id: string;
  subject: Subject;
  course: string;  // 예: "초3-1"
  types: CurriculumType[];
}

export interface SelectedType {
  curriculumId: string;
  course: string;
  typeId: string;
  majorUnit: string;
  minorUnit: string;
  typeName: string;
  difficulty: Difficulty; // 유형·난이도 조합의 난이도
  problemCount: number; // 사용자가 입력한 문제 수
  maxCount: { basic: number; intermediate: number; advanced: number };
  importantCount: { basic: number; intermediate: number; advanced: number }; // 난이도별 중요 문제 수
}

export interface StudentAssignment {
  studentId: string;
  studentName: string;
  classGroup: string;
  status: StudentTaskStatus;
  score?: number;
  correctCount?: number;
  totalCount?: number;
  submittedAt?: string;
  timedOutAt?: string;
  printStatus: "not_printed" | "printed";
  problemCount?: number;
}

export type ProblemScope = "all" | "important"; // 하위 호환용

export interface TaskItem {
  id: string;
  subject: Subject;
  name: string;
  course: string;
  status: TaskStatus;
  difficulties: Difficulty[]; // 하위 호환용: selectedTypes[].difficulty 고유 목록
  problemMode: ProblemMode;
  prioritizeUnsolved: boolean;
  timeLimit?: number; // 분 단위, undefined = 미설정
  problemScope?: ProblemScope; // 하위 호환용
  onlyImportant?: boolean; // 중요 문제만 출제
  onlyImportantType?: boolean; // 중요 유형만 출제
  selectedTypes: SelectedType[];
  totalProblems: number;
  createdAt: string;
  assignedStudents: StudentAssignment[];
  assignedClasses?: string[];
  individualStudentIds?: string[];
}

