// ─────────────────────────────────────────────

const TASK_SPEC_MAP: Record<string, { typeCount: number; problemCount: number; difficulty: Difficulty }> = {
  // 수학 소형 (유형 5~8개, 문제 10~16문항)
  "task-001": { typeCount: 5, problemCount: 2, difficulty: "intermediate" },
  "task-002": { typeCount: 5, problemCount: 2, difficulty: "advanced" },
  "task-003": { typeCount: 5, problemCount: 2, difficulty: "basic" },
  "task-math-004": { typeCount: 8, problemCount: 2, difficulty: "basic" },
  "task-math-005": { typeCount: 8, problemCount: 2, difficulty: "intermediate" },
  // 과학 소형 (유형 5개, 문제 10문항)
  "task-sci-102": { typeCount: 5, problemCount: 2, difficulty: "intermediate" },
  "task-sci-103": { typeCount: 5, problemCount: 2, difficulty: "advanced" },
  "task-sci-104": { typeCount: 5, problemCount: 2, difficulty: "basic" },

  // 수학 중형 (유형 12~18개, 문제 24~36문항)
  "task-math-006": { typeCount: 12, problemCount: 2, difficulty: "intermediate" },
  "task-math-007": { typeCount: 12, problemCount: 2, difficulty: "advanced" },
  "task-math-008": { typeCount: 12, problemCount: 2, difficulty: "basic" },
  "task-math-009": { typeCount: 18, problemCount: 2, difficulty: "intermediate" },
  // 과학 중형 (유형 12~18개, 문제 24~36문항)
  "task-sci-105": { typeCount: 12, problemCount: 2, difficulty: "intermediate" },
  "task-sci-106": { typeCount: 12, problemCount: 2, difficulty: "advanced" },
  "task-sci-107": { typeCount: 12, problemCount: 2, difficulty: "basic" },
  "task-sci-108": { typeCount: 18, problemCount: 2, difficulty: "intermediate" },

  // 수학 대형 (유형 25~100개, 문제 50~300문항)
  "task-math-010": { typeCount: 25, problemCount: 2, difficulty: "intermediate" },
  "task-math-011": { typeCount: 40, problemCount: 2, difficulty: "basic" },
  "task-math-012": { typeCount: 62, problemCount: 2, difficulty: "intermediate" },
  "task-101": { typeCount: 100, problemCount: 3, difficulty: "intermediate" },
  // 과학 대형 (유형 25~93개, 문제 50~186문항)
  "task-sci-109": { typeCount: 25, problemCount: 2, difficulty: "intermediate" },
  "task-sci-110": { typeCount: 40, problemCount: 2, difficulty: "intermediate" },
  "task-sci-111": { typeCount: 62, problemCount: 2, difficulty: "intermediate" },
  "task-sci-112": { typeCount: 93, problemCount: 2, difficulty: "intermediate" },
};

INITIAL_TASKS.forEach(task => {
  const spec = TASK_SPEC_MAP[task.id];
  if (!spec) return;

  const curricula = task.subject === "math" ? MATH_CURRICULA : SCIENCE_CURRICULA;
  const curriculum = curricula.find(c => c.course === task.course);
  if (!curriculum) return;

  // 고유한 유형 수집
  const seen = new Set<string>();
  const uniqueTypes = curriculum.types.filter(t => {
    if (seen.has(t.id)) return false;
    seen.add(t.id);
    return true;
  });

  const targets = uniqueTypes.slice(0, spec.typeCount);
  
  task.selectedTypes = targets.map(t => ({
    curriculumId: curriculum.id,
    course: curriculum.course,
    typeId: t.id,
    majorUnit: t.majorUnit,
    minorUnit: t.minorUnit,
    typeName: t.typeName,
    difficulty: spec.difficulty,
    problemCount: spec.problemCount,
    maxCount: {
      basic: spec.difficulty === "basic" ? 3 : 0,
      intermediate: spec.difficulty === "intermediate" ? 3 : 0,
      advanced: spec.difficulty === "advanced" ? 3 : 0,
    },
    importantCount: {
      basic: spec.difficulty === "basic" ? 1 : 0,
      intermediate: spec.difficulty === "intermediate" ? 1 : 0,
      advanced: spec.difficulty === "advanced" ? 1 : 0,
    }
  }));

  // totalProblems 갱신
  task.totalProblems = task.selectedTypes.length * spec.problemCount;
  
  // difficulties 갱신
  task.difficulties = [spec.difficulty];

  // 학생 제출 문항 수 보정
  if (task.assignedStudents && task.assignedStudents.length > 0) {
    task.assignedStudents.forEach(stu => {
      stu.problemCount = task.totalProblems;
    });
  }

  // ─────────────────────────────────────────────
  // 목데이터 전체 정합성 자가치유 (Self-Healing)
  // ─────────────────────────────────────────────
  // 1. assignedClasses가 지정되어 있는 반 배정 과제의 경우
  if (task.assignedClasses && task.assignedClasses.length > 0) {
    const allGlobalStudents = getAdaptedSampleStudents();
    
    // 예전 반 명칭 매핑 (선생님/학생 관리의 등록된 반 정보와 동적으로 매칭되도록 연동!)
    const storedClasses = getStoredClasses();
    const mappedClasses = task.assignedClasses.map(c => {
      // 1. 이미 등록된 반 명칭과 동일하다면 그대로 반환
      if (storedClasses.some(sc => sc.name === c)) {
        return c;
      }
      
      // 2. 과거 목데이터 번호 반(1반, 2반, 3반)을 등록된 반 리스트의 순서대로 동적 매칭
      if (c === "1반" && storedClasses[0]) return storedClasses[0].name;
      if (c === "2반" && storedClasses[1]) return storedClasses[1].name;
      if (c === "3반" && storedClasses[2]) return storedClasses[2].name;
      
      // 3. 구버전 예전 한글 명칭(초3A반, 초4B반, 초5C반)도 등록된 반 리스트 순서대로 매칭
      if (c === "초3A반" && storedClasses[0]) return storedClasses[0].name;
      if (c === "초4B반" && storedClasses[1]) return storedClasses[1].name;
      if (c === "초5C반" && storedClasses[2]) return storedClasses[2].name;
      
      return c;
    });

    // 해당 반에 소속된 실제 동적 학생들 필터링
    const classStudents = allGlobalStudents.filter(s => mappedClasses.includes(s.classGroup));

    if (classStudents.length > 0) {
      // 기존 assignedStudents 에서 진행 상태("in_progress", "submitted")를 추출
      const activeStates = task.assignedStudents
        .filter(as => as.status !== "not_started")
        .map(as => ({
          status: as.status,
          score: as.score,
          correctCount: as.correctCount,
          totalCount: as.totalCount,
          submittedAt: as.submittedAt
        }));

      let activeIndex = 0;

      // 실제 학생 명단으로 assignedStudents 배열을 100% 리셋 및 동기화!
      task.assignedStudents = classStudents.map(s => {
        // 기존에 진행 중이거나 제출 완료한 학생이 하나라도 있었다면, 첫 번째 학생(들)에게 그 상태를 이관
        let state: any = { status: "not_started" };
        if (activeIndex < activeStates.length) {
          state = activeStates[activeIndex++];
        }

        return {
          studentId: s.studentId,
          studentName: s.studentName,
          classGroup: s.classGroup,
          status: state.status,
          score: state.score,
          correctCount: state.correctCount,
          totalCount: state.totalCount,
          submittedAt: state.submittedAt,
          printStatus: "not_printed" as const,
          problemCount: task.totalProblems
        };
      });
      
      // assignedClasses 명칭도 매핑된 명칭으로 표준화
      task.assignedClasses = mappedClasses;
    }
  } 
  // 2. assignedClasses가 없고 individualStudentIds가 있는 개별 배정 과제의 경우
  else if (task.individualStudentIds && task.individualStudentIds.length > 0) {
    const allGlobalStudents = getAdaptedSampleStudents();
    
    // 고스트 학생을 배제하고, 실제 존재하는 학생들만 필터링하여 매핑
    const validStudents: typeof task.assignedStudents = [];
    const validIds: string[] = [];

    task.assignedStudents.forEach(as => {
      // 이름 기준으로 매핑 우선 시도
      const realStudent = allGlobalStudents.find(s => s.studentName === as.studentName);
      if (realStudent) {
        validStudents.push({
          ...as,
          studentId: realStudent.studentId,
          classGroup: realStudent.classGroup,
          problemCount: task.totalProblems
        });
        validIds.push(realStudent.studentId);
      }
    });

    if (validStudents.length > 0) {
      task.assignedStudents = validStudents;
      task.individualStudentIds = validIds;
    } else {
      // 이름 매핑조차 안 되는 고스트 학생만 있는 경우, 실제 학생 중 일부를 샘플로 배정하여 완전히 썩은 데이터 방지
      // 이와 동시에 기존에 고스트 학생이 들고 있던 완료(submitted) 및 진행중(in_progress) 등의 진행 상태를 그대로 이관합니다! (QA 편의성 극대화)
      const sampleStudents = allGlobalStudents.slice(0, Math.min(5, allGlobalStudents.length));
      
      const activeStates = task.assignedStudents
        .filter(as => as.status !== "not_started")
        .map(as => ({
          status: as.status,
          score: as.score,
          correctCount: as.correctCount,
          totalCount: as.totalCount,
          submittedAt: as.submittedAt
        }));

      let activeIndex = 0;

      task.assignedStudents = sampleStudents.map(s => {
        let state: any = { status: "not_started" };
        if (activeIndex < activeStates.length) {
          state = activeStates[activeIndex++];
        }

        return {
          studentId: s.studentId,
          studentName: s.studentName,
          classGroup: s.classGroup,
          status: state.status,
          score: state.score,
          correctCount: state.correctCount,
          totalCount: state.totalCount,
          submittedAt: state.submittedAt,
          printStatus: "not_printed" as const,
          problemCount: task.totalProblems
        };
      });
      task.individualStudentIds = sampleStudents.map(s => s.studentId);
    }
  }
});

